<script setup>
import ProductionEditor from './ProductionEditor.vue';
import ReferralDetails from './ReferralDetails.vue';
const referral=ref(null);
import {computed,ref,watch,onBeforeUnmount} from 'vue';
const props=defineProps({module:Object,data:Object,saveRecord:Function,prepare:Function});
const exporting=ref(''),exportError=ref('');
async function exportPdf(row){if(exporting.value)return;exporting.value=row.id;exportError.value='';try{const full=await props.prepare(row,'productionOrders',true);const {downloadProductionOrderPdf}=await import('../../../../web/production-order-pdf.js');await downloadProductionOrderPdf(full);}catch(e){exportError.value=e.message||'No se pudo descargar el PDF.';}finally{exporting.value='';}}
const editor=ref(null),opening=ref(false),openError=ref('');
async function openEditor(row=null){if(opening.value)return;opening.value=true;openError.value='';const group=props.module.id;try{const record=await props.prepare(row,group);if(group===props.module.id)editor.value={record,creating:!row};}catch(e){openError.value=e.message;}finally{opening.value=false;}}
const search=ref(''),status=ref(''),page=ref(1),size=ref(25),dialog=ref(null),selected=ref(null);
const columns=computed(()=>({products:[['code','Código'],['name','Nombre'],['price','Precio comercial'],['tax','IVA (%)']],productionOrders:[['number','Número'],['accountName','Cuenta'],['status','Estado'],['date','Creación'],['deliveryDate','Fecha esperada'],['approvalDate','Aprobación'],['comments','Comentarios']],referrals:[['number','Número'],['accountName','Cuenta'],['date','Creación'],['deliveryDate','Entrega'],['comments','Comentarios']],processes:[['name','Nombre'],['description','Descripción']]}[props.module.id]||[]));
const labels={CREATED:'Creado',VOIDED:'Anulada',VERIFIED:'Verificado',ITEMS_DELIVERED:'Ítems entregados',APPROVED:'Aprobado',DELIVERED:'Entregado'};
function display(k,v){if(v==null||v==='')return '—';if(k==='status')return labels[v]||v;if(k==='price')return new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP'}).format(Number(v));if(k.endsWith('Date')||k==='date')return String(v).split('-').reverse().join('/');return v;}
const source=computed(()=>props.data?.[props.module.id]||[]),statuses=computed(()=>[...new Set(source.value.map(r=>r.status).filter(Boolean))]);
const rows=computed(()=>source.value.filter(r=>(!status.value||r.status===status.value)&&columns.value.some(([k])=>String(display(k,r[k])).toLocaleLowerCase('es').includes(search.value.trim().toLocaleLowerCase('es')))).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(a.name||a.number).localeCompare(String(b.name||b.number),'es',{numeric:true})));
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/size.value))),visible=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));
watch([search,status,size,()=>props.module.id],()=>{page.value=1;editor.value=null;referral.value=null;dialog.value?.close();selected.value=null;});
function view(row){if(props.module.id==='referrals'){referral.value=row;return;}if(['products','productionOrders'].includes(props.module.id)){openEditor(row);return;}selected.value=row;dialog.value.showModal();}
const host=(()=>{try{return window.parent.location.origin===window.location.origin?window.parent.document.body:document.body;}catch{return document.body;}})();
onBeforeUnmount(()=>dialog.value?.close());
</script>
<template>
<p v-if="data?.loading" role="status">Cargando Producción…</p><p v-else-if="data?.error" role="alert">{{ data.error }}</p><p v-else-if="data?.unavailable">La información importada de Producción corresponde a DyD.</p><p v-else-if="!data||data.pending">La consulta de Producción está pendiente de habilitación.</p>
<template v-else><p v-if="exportError" role="alert">{{ exportError }}</p><div class="commercial-pagination"><p v-if="openError" role="alert">{{ openError }}</p><span v-if="opening" role="status">Cargando ficha…</span><button v-if="data.canEdit&&['products','productionOrders'].includes(module.id)" type="button" :disabled="opening" @click="openEditor()">+ Crear {{ module.id==='products'?'producto':'orden de producción' }}</button></div><div class="commercial-filters"><label>Buscar<input v-model="search" type="search" placeholder="Buscar en esta tabla"></label><label v-if="statuses.length">Estado<select v-model="status"><option value="">Todos los estados</option><option v-for="s in statuses" :key="s" :value="s">{{ labels[s]||s }}</option></select></label><label>Por página<select v-model.number="size"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label></div>
<div class="process-data-table-wrap"><table class="process-data-table" :aria-label="module.label"><thead><tr><th v-for="[k,label] in columns" :key="k" scope="col">{{ label }}</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td v-for="[k] in columns" :key="k">{{ display(k,row[k]) }}</td><td><button type="button" class="commercial-view-account" title="Ver información" aria-label="Ver información" @click="view(row)"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button><button v-if="module.id==='productionOrders'" type="button" class="commercial-view-account" :disabled="!!exporting" :title="exporting===row.id?'Generando PDF…':'Descargar PDF'" aria-label="Descargar orden de producción en PDF" @click="exportPdf(row)"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M12 11v7m-3-3 3 3 3-3"/></svg></button></td></tr><tr v-if="!visible.length"><td :colspan="columns.length+1">{{ source.length?'No hay coincidencias.':'No hay registros en la copia migrada.' }}</td></tr></tbody></table></div>
<div class="commercial-pagination"><span>{{ rows.length }} registros · Página {{ page }} de {{ pages }}</span><button :disabled="page<=1" @click="page--">Anterior</button><button :disabled="page>=pages" @click="page++">Siguiente</button></div></template>
<ReferralDetails v-if="referral" :record="referral" @close="referral=null" /><ProductionEditor v-if="editor" :key="module.id" :group="module.id" :record="editor.record" :creating="editor.creating" :data="data" :save-record="saveRecord" @close="editor=null" /><Teleport :to="host"><link rel="stylesheet" href="/procesos/account-detail.css"><dialog ref="dialog" class="sigmyp-account-dialog" aria-labelledby="production-title"><header class="sigmyp-account-header"><h2 id="production-title">{{ selected?.number||selected?.name||module.label }}</h2><button type="button" class="sigmyp-account-close" @click="dialog.close()">Cerrar ✕</button></header><div v-if="selected" style="padding:24px"><dl><div v-for="[k,label] in columns" :key="k" style="margin-bottom:12px"><dt><strong>{{ label }}</strong></dt><dd style="margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere">{{ display(k,selected[k]) }}</dd></div><template v-if="module.id==='products'"><dt><strong>Descripción</strong></dt><dd>{{ selected.description||'—' }}</dd><dt><strong>Comentarios</strong></dt><dd>{{ selected.comments||'—' }}</dd></template></dl><template v-if="selected.lines"><h3>Productos</h3><div class="sigmyp-account-table-scroll"><table><thead><tr><th>Código</th><th>Producto</th><th>Cantidad</th><th>Comentarios</th></tr></thead><tbody><tr v-for="(line,i) in selected.lines" :key="i"><td>{{ line.code }}</td><td>{{ line.name }}</td><td>{{ line.quantity }}</td><td>{{ line.comments }}</td></tr><tr v-if="!selected.lines.length"><td colspan="4">Sin detalle de productos registrado.</td></tr></tbody></table></div></template></div></dialog></Teleport>
</template>
